  var model = core.make({"id":"breech","kind":"drill","level":"resident","review":"ai_drafted","timeLimitSec":480,"title":{"en":"Assisted vaginal breech birth drill","hi":"सहायता प्राप्त योनि ब्रीच प्रसव ड्रिल"},"scenario":{"en":"A woman at term arrives at 8 cm with an undiagnosed frank breech. The estimated fetal weight is not large, the head is flexed on scan, she has no uterine scar, and a skilled attendant and theatre are available. Teaching scenario, not a real patient.","hi":"पूर्ण अवधि की एक महिला 8 cm पर आती है, जिसका फ़्रैंक ब्रीच पहले पता नहीं था। अनुमानित भ्रूण वज़न बड़ा नहीं है, स्कैन पर सिर मुड़ा (फ़्लेक्स्ड) है, गर्भाशय पर कोई निशान नहीं है, और कुशल सहायक व ऑपरेशन थिएटर उपलब्ध हैं। यह शिक्षण परिदृश्य है, असली मरीज़ नहीं।"},"sources":[{"label":"RCOG Green-top Guideline No. 20b: Management of Breech Presentation (March 2017). Copy opened at this URL","url":"https://tjodistanbul.org/uploads/management-of-breech-presentation-no.20b-march-2017.pdf"},{"label":"WHO. Managing Complications in Pregnancy and Childbirth, 2nd edition (2017): breech presentation and breech birth","url":"https://iris.who.int/server/api/core/bitstreams/3bda1306-da5d-487d-b2ad-aff995112a7a/content"}],"stages":[{"id":"mode","src":0,"timeSec":90,"prompt":{"en":"She is at 8 cm and contracting well. Mode of birth?","hi":"वह 8 cm पर है और अच्छे संकुचन हैं। प्रसव का तरीका?"},"options":[{"id":"a","correct":true,"critical":true,"text":{"en":"Counsel her and support a vaginal breech birth with the skilled attendant present and theatre ready.","hi":"उसे परामर्श दें और कुशल सहायक की मौजूदगी व थिएटर तैयार रखते हुए योनि ब्रीच प्रसव में सहयोग करें।"},"feedback":{"en":"RCOG: women near or in the active second stage should not be routinely offered caesarean. WHO lists frank breech, a flexed head and a fetus not too large among the conditions for vaginal breech birth.","hi":"RCOG: सक्रिय दूसरे चरण के पास या उसमें महिलाओं को नियमित रूप से सिज़ेरियन नहीं देना चाहिए। WHO फ़्रैंक ब्रीच, मुड़ा सिर और बहुत बड़ा न होने वाले भ्रूण को योनि ब्रीच प्रसव की शर्तों में गिनता है।"}},{"id":"b","correct":false,"text":{"en":"Rupture the membranes to speed things up.","hi":"जल्दी करने के लिए झिल्ली फोड़ दें।"},"feedback":{"en":"Amniotomy is reserved for definite indications in breech labour because of cord compression and prolapse.","hi":"ब्रीच प्रसव में कॉर्ड दबने और बाहर आने के खतरे के कारण झिल्ली फोड़ना केवल स्पष्ट कारण पर।"}},{"id":"c","correct":false,"text":{"en":"Routine emergency caesarean because it is breech.","hi":"ब्रीच होने के कारण नियमित आपात सिज़ेरियन।"},"feedback":{"en":"Not routine this late in labour; individualise and support a skilled vaginal birth.","hi":"प्रसव के इतने आगे के चरण में यह नियमित नहीं; व्यक्तिगत निर्णय लें और कुशल योनि प्रसव में सहयोग करें।"}}]},{"id":"pushing","src":0,"timeSec":60,"prompt":{"en":"She reaches full dilatation. When does active pushing start?","hi":"वह पूरे फैलाव तक पहुँच गई है। सक्रिय ज़ोर कब शुरू हो?"},"options":[{"id":"a","correct":true,"critical":true,"text":{"en":"Allow a passive second stage for the breech to descend; encourage pushing only when the breech is visible. If it is not visible within 2 hours, recommend caesarean.","hi":"ब्रीच के नीचे आने के लिए निष्क्रिय दूसरा चरण होने दें; ज़ोर तभी लगवाएँ जब ब्रीच दिखने लगे। 2 घंटे में न दिखे तो सिज़ेरियन की सलाह दें।"},"feedback":{"en":"RCOG: adequate descent in the passive second stage is a prerequisite for the active second stage.","hi":"RCOG: निष्क्रिय दूसरे चरण में पर्याप्त उतराव सक्रिय दूसरे चरण की शर्त है।"}},{"id":"b","correct":false,"text":{"en":"Push from full dilatation, with oxytocin routinely.","hi":"पूरे फैलाव से ज़ोर, साथ में नियमित ऑक्सीटोसिन।"},"feedback":{"en":"Pushing waits until the breech is visible; oxytocin only for low contraction frequency with an epidural.","hi":"ज़ोर तब तक रुके जब तक ब्रीच न दिखे; ऑक्सीटोसिन केवल एपिड्यूरल के साथ कम संकुचन पर।"}}]},{"id":"handsoff","src":0,"timeSec":45,"prompt":{"en":"The buttocks are delivering. What do your hands do?","hi":"नितंब बाहर आ रहे हैं। आपके हाथ क्या करें?"},"options":[{"id":"a","correct":true,"critical":true,"text":{"en":"Hands off: no traction. If you must hold, grasp the pelvic girdle, never the abdomen or flanks, and never hyperextend the neck.","hi":"हाथ दूर: कोई खिंचाव नहीं। पकड़ना ज़रूरी हो तो कूल्हे की हड्डी पकड़ें, पेट या बगल कभी नहीं, और गर्दन कभी ज़्यादा पीछे न मोड़ें।"},"feedback":{"en":"RCOG: a hands-off approach, with timely intervention if progress stops. Traction and tactile stimulation extend the arms and head.","hi":"RCOG: हाथ दूर रखने का तरीका, प्रगति रुकने पर समय पर हस्तक्षेप। खिंचाव और स्पर्श से बाँहें और सिर पीछे मुड़ जाते हैं।"}},{"id":"b","correct":false,"text":{"en":"Pull gently on the legs with each contraction.","hi":"हर संकुचन के साथ पैरों को धीरे खींचें।"},"feedback":{"en":"Traction causes arm extension and head deflexion. Hands off.","hi":"खिंचाव से बाँहें ऊपर और सिर पीछे चला जाता है। हाथ दूर रखें।"}}]},{"id":"timing","src":0,"timeSec":45,"prompt":{"en":"When must you step in to expedite the birth?","hi":"प्रसव जल्दी कराने के लिए कब हस्तक्षेप करना चाहिए?"},"options":[{"id":"a","correct":true,"critical":true,"text":{"en":"If the baby shows poor tone or colour, or there is a delay of more than 5 minutes from buttocks to head, or more than 3 minutes from umbilicus to head.","hi":"यदि शिशु का तनाव (टोन) या रंग खराब हो, या नितंब से सिर तक 5 मिनट से अधिक, या नाभि से सिर तक 3 मिनट से अधिक की देरी हो।"},"feedback":{"en":"RCOG time limits. Once the buttocks pass the perineum, cord compression is common.","hi":"RCOG की समय सीमाएँ। नितंब पेरिनियम पार करने के बाद कॉर्ड दबना आम है।"}},{"id":"b","correct":false,"text":{"en":"Only after 15 minutes without progress.","hi":"केवल 15 मिनट बिना प्रगति के बाद।"},"feedback":{"en":"Far too late: 5 minutes from buttocks, 3 from umbilicus.","hi":"बहुत देर: नितंब से 5 मिनट, नाभि से 3 मिनट।"}}]},{"id":"arms","src":1,"timeSec":45,"prompt":{"en":"The scapulae are visible but the arms are stretched above the head. Manoeuvre?","hi":"कंधे की हड्डियाँ दिख रही हैं पर बाँहें सिर के ऊपर तनी हैं। कौन सा मैनूवर?"},"options":[{"id":"a","correct":true,"critical":true,"text":{"en":"Lovset: hold the hips, turn the baby half a circle with the back uppermost so the posterior arm comes anterior and delivers under the pubic arch; turn back for the other arm.","hi":"लोवसेट: कूल्हे पकड़ें, पीठ ऊपर रखते हुए शिशु को आधा घुमाएँ ताकि पीछे की बाँह आगे आकर प्यूबिक आर्च के नीचे से निकले; दूसरी बाँह के लिए वापस घुमाएँ।"},"feedback":{"en":"WHO and RCOG both use Lovset's manoeuvre for extended or nuchal arms.","hi":"WHO और RCOG दोनों तनी या गर्दन के पीछे फँसी बाँहों के लिए लोवसेट मैनूवर बताते हैं।"}},{"id":"b","correct":false,"text":{"en":"Pull the trunk down harder until the arms come.","hi":"बाँहें आने तक धड़ को और ज़ोर से नीचे खींचें।"},"feedback":{"en":"Traction makes extended arms worse. Rotate with Lovset.","hi":"खिंचाव से तनी बाँहें और बिगड़ती हैं। लोवसेट से घुमाएँ।"}}]},{"id":"head","src":0,"timeSec":45,"prompt":{"en":"The arms are out. The after-coming head is not delivering. Next?","hi":"बाँहें निकल गईं। बाद में आने वाला सिर नहीं निकल रहा। अगला?"},"options":[{"id":"a","correct":true,"critical":true,"next":"end","text":{"en":"Mauriceau-Smellie-Veit to flex the head (or forceps), with an assistant giving suprapubic pressure to aid flexion.","hi":"सिर मोड़ने के लिए मॉरिसो-स्मेली-वाइट (या फ़ोरसेप्स), सहायक सुप्राप्यूबिक दबाव देकर मोड़ने में मदद करे।"},"feedback":{"en":"RCOG: delivery by Mauriceau-Smellie-Veit or forceps; suprapubic pressure helps an extended neck.","hi":"RCOG: मॉरिसो-स्मेली-वाइट या फ़ोरसेप्स से प्रसव; सुप्राप्यूबिक दबाव पीछे मुड़ी गर्दन में मदद करता है।"}},{"id":"b","correct":false,"next":"end","text":{"en":"Burns-Marshall: swing the body up over the mother's abdomen.","hi":"बर्न्स-मार्शल: शरीर को माँ के पेट की ओर ऊपर घुमाएँ।"},"feedback":{"en":"Burns-Marshall suits an after-coming head that is already flexed and descending. When the head is stuck, Mauriceau-Smellie-Veit (or forceps) actively flexes it. Swinging the body up too far can over-extend the neck.","hi":"बर्न्स-मार्शल उस बाद में आने वाले सिर के लिए है जो पहले से मुड़ा हुआ है और नीचे आ रहा है। सिर फँसा हो तो मॉरिसो-स्मेली-वाइट (या फ़ोरसेप्स) सक्रिय रूप से सिर को मोड़ता है। शरीर को बहुत ऊपर घुमाने से गर्दन ज़्यादा पीछे मुड़ सकती है।"}}]}]});
